class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def mergeBetweenZeros(nums):
    head = build(nums)
    out = ListNode()
    tail = out
    s = 0
    cur = head.next
    while cur:
        if cur.val == 0:
            tail.next = ListNode(s)
            tail = tail.next
            s = 0
        else:
            s += cur.val
        cur = cur.next
    return dump(out.next)
